      "\\lambda_g^{tr}/3": "λ_g^tr: transport-side group mean free path\n(the coefficient of the diffusion term of H_g is λ_g^tr/3)",
      "H_g/\\lambda_g^{abs}": "H_g: group transport field\nλ_g^abs: absorption-side group mean free path\n(the decay term of the equation for H_g)",
      "H_g=0": "H_g: group transport field\n(the rows of void and similar cells are identity rows with H_g=0)",
      "V/\\lambda_g^{abs}": "V: cell volume\nλ_g^abs: absorption-side group mean free path\n(the term added to the diagonal of the operator of each group in 2D RZ)",
      "P(\\beta)=1-e^{-\\beta}(\\beta^4+4\\beta^3+12\\beta^2+24\\beta+24)/24": "P: cumulative distribution of the SH flux\nβ: normalized electron energy E/(k_B T_e)\n(the analytic antiderivative of β⁴e^{-β}/24)",
      "U_g=\\xi_gq_{SH}": "U_g: group share of the local SH flux\nξ_g: group weight\nq_SH: SH heat flux",
      "\\xi_g=P(\\beta_g)-P(\\beta_{g-1})": "ξ_g: group weight\nP: cumulative distribution\nβ_g: group edge normalized by the local temperature",
