      "\\beta=E/(k_BT_e)": "β: electron energy normalized by the local temperature\nE: electron energy\nk_B·T_e: electron thermal energy",
      "\\beta_g": "β_g: group edge E_g normalized by the local temperature of the cell",
      "\\hat\\beta=E/(k_B\\max T_e)": "β̂: global normalized energy\nE: electron energy\nk_B·max T_e: largest electron thermal energy of the step",
      "\\hat\\beta_{max}": "β̂_max: upper end of the group edges (snb_E_max_over_Te, default 20)",
      "\\max T_e": "max T_e: largest electron temperature over all cells in the step",
      "k_B\\max T_e": "k_B: eV-to-erg conversion\nmax T_e: largest electron temperature\n(the thermal energy that normalizes β̂)",
      "\\varepsilon_g": "ε_g: representative energy of a group, (E_{g−1}+E_g)/2",
      "\\lambda_g": "λ_g: mean free path of the electrons at the representative energy ε_g of the group (formula in the SNB section)",
      "\\lambda_g^{abs}": "λ_g^abs: absorption-side group mean free path (sets the distance over which H_g decays away from the source)",
      "\\lambda_g^{tr}": "λ_g^tr: transport-side group mean free path (sets how fast H_g spreads)",
      "\\theta_c": "θ_c: flux-limiter factor of cell c",
      "\\min(\\theta_c,\\theta_d)": "θ_c, θ_d: flux-limiter factors of cells c and d\n(the value multiplied onto the pair power)",
      "q_{raw}": "q_raw: heat flux before limiting",
      "E_g": "E_g: SNB group edge mapped to physical energy [erg]",
      "\\beta_g=E_g/(k_BT_e)": "β_g: group edge reread in the cell's local temperature\nE_g: physical-energy group edge\nk_B·T_e: electron thermal energy",
      "\\theta": "θ: flux-limiter factor 1/(1+|q_raw|/q_max)",
      "P(\\beta)": "P: cumulative SH-flux distribution\nβ: normalized electron energy",
      "(1-R)\\propto k^2": "R: flux-reduction ratio\nk: wavenumber\n(SNB asymptotics at small k)",
      "1/\\lambda_g^{tr}\\mathrel{+}=|e\\mathcal E|/\\varepsilon_g": "λ_g^tr: transport-side group mean free path\ne: elementary charge\nℰ: magnitude of the local electrostatic field\nε_g: representative energy of the group\n(for snb_efield=\"local\"; shortens the transport side only)",
